-- Generated by vfs_scaffold_auth (postgres): the app's own user accounts. Idempotent: safe to re-run.
-- The auth module also applies this file when the backend starts. Change it with a new numbered file.

CREATE TABLE IF NOT EXISTS "app_users" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(320) NOT NULL UNIQUE,
  "name" varchar(120),
  "password_hash" text NOT NULL,
  "disabled" boolean NOT NULL DEFAULT FALSE,
  "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "app_roles" (
  "name" varchar(64) PRIMARY KEY
);

CREATE TABLE IF NOT EXISTS "app_user_roles" (
  "user_id" bigint NOT NULL REFERENCES "app_users"("id") ON DELETE CASCADE,
  "role" varchar(64) NOT NULL REFERENCES "app_roles"("name") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "app_user_roles_user_role_uidx" ON "app_user_roles" ("user_id", "role");

CREATE TABLE IF NOT EXISTS "app_sessions" (
  "id" varchar(64) PRIMARY KEY,
  "user_id" bigint NOT NULL REFERENCES "app_users"("id") ON DELETE CASCADE,
  "expires_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS "app_sessions_user_idx" ON "app_sessions" ("user_id");
CREATE INDEX IF NOT EXISTS "app_sessions_expires_idx" ON "app_sessions" ("expires_at");

CREATE TABLE IF NOT EXISTS "app_invites" (
  "code_hash" varchar(64) PRIMARY KEY,
  "email" varchar(320),
  "roles" text NOT NULL DEFAULT '[]',
  "created_by" bigint REFERENCES "app_users"("id") ON DELETE SET NULL,
  "expires_at" timestamptz NOT NULL,
  "used_at" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT now()
);

INSERT INTO "app_roles" ("name") VALUES ('admin') ON CONFLICT DO NOTHING;
